// src/pages/RegisterPage.js
import { useState } from 'react';
import { Link } from 'react-router-dom';

function RegisterPage() {
  const [darkMode, setDarkMode] = useState(false);
  const toggleTheme = () => setDarkMode(prev => !prev);

  const [formData, setFormData] = useState({
    fullname: '',
    username: '',
    password: '',
    confirmPassword: '',
    dob: '',
    level: '',
    terms: false
  });

  const [submitted, setSubmitted] = useState(false);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({
      ...formData,
      [name]: type === 'checkbox' ? checked : value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.password !== formData.confirmPassword) {
      alert('Passwords do not match!');
      return;
    }
    setSubmitted(true);
  };

  return (
    <div className={darkMode ? 'dark-mode' : ''}>
      <header className="header">
        <h1>Registration</h1>
        <nav>
          <ul className="navList">
            <li><Link to="/">Home</Link></li>
            <li><Link to="/about">About</Link></li>
            <li><Link to="/contact">Contact</Link></li>
            <li><Link to="/register" className="active">Register</Link></li>
            <li><Link to="/game">Game</Link></li>
          </ul>
        </nav>
      </header>

      <button className="theme-toggle" onClick={toggleTheme}>Toggle Dark/Light</button>

      {submitted ? (
        <p style={{textAlign: 'center', marginTop: '30px'}}>Thank you for registering!</p>
      ) : (
        <form onSubmit={handleSubmit} className="register-form">
          <label>Full Name</label>
          <input type="text" name="fullname" value={formData.fullname} onChange={handleChange} required />

          <label>Username</label>
          <input type="text" name="username" value={formData.username} onChange={handleChange} required />

          <label>Password</label>
          <input type="password" name="password" value={formData.password} onChange={handleChange} required />

          <label>Confirm Password</label>
          <input type="password" name="confirmPassword" value={formData.confirmPassword} onChange={handleChange} required />

          <label>Date of Birth</label>
          <input type="date" name="dob" value={formData.dob} onChange={handleChange} required />

          <label>Interest Category</label>
          <div className="options">
            <label><input type="radio" name="level" value="Beginner" onChange={handleChange} required /> Beginner</label>
            <label><input type="radio" name="level" value="Intermediate" onChange={handleChange} /> Intermediate</label>
            <label><input type="radio" name="level" value="Expert" onChange={handleChange} /> Expert</label>
          </div>

          <label>
            <input type="checkbox" name="terms" checked={formData.terms} onChange={handleChange} required />
            I agree to the terms and conditions
          </label>

          <input type="submit" value="Register" />
        </form>
      )}

      <footer className="footer">
        <p>Contact: dxxxxxxxxxxx@gmail.com | Phone: 09xxxxxxx8</p>
        <p>&copy; 2026 My Personal Portfolio. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default RegisterPage;
